# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DOĞADAKİ DÖRT TEMEL KUVVET (BÜYÜKTEN KÜÇÜĞE SIRALAMA)</text>\n  <rect x="20" y="45" width="320" height="90" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">1. GÜÇLÜ NÜKLEER KUVVET (En Şiddetli)</text>\n  <text x="35" y="86" font-size="10.5" fill="#7f1d1d">• Görevi: Atom çekirdeğindeki proton ve nötronları</text>\n  <text x="43" y="101" font-size="10.5" fill="#7f1d1d">(hadronları/kuarkları) dağılmadan bir arada tutar.</text>\n  <text x="35" y="118" font-size="10.5" font-weight="bold" fill="#b91c1c">• Menzil: Çok kısa (~10⁻¹⁵ m) · Taşıyıcı: Gluon</text>\n  <rect x="360" y="45" width="320" height="90" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. ELEKTROMANYETİK KUVVET</text>\n  <text x="375" y="86" font-size="10.5" fill="#1e3a8a">• Görevi: Elektrik yüklü parçacıklar ve mıknatıslar</text>\n  <text x="383" y="101" font-size="10.5" fill="#1e3a8a">arasındaki çekme/itme kuvveti; atom ve molekülü tutar.</text>\n  <text x="375" y="118" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Menzil: Sonsuz (1/d²) · Taşıyıcı: Foton</text>\n  <rect x="20" y="150" width="320" height="90" rx="8" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="180" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">3. ZAYIF NÜKLEER KUVVET</text>\n  <text x="35" y="191" font-size="10.5" fill="#713f12">• Görevi: Kararsız atom çekirdeklerinin radyoaktif</text>\n  <text x="43" y="206" font-size="10.5" fill="#713f12">bozunmasından (beta bozunması) sorumludur.</text>\n  <text x="35" y="223" font-size="10.5" font-weight="bold" fill="#a16207">• Menzil: Çok kısa (~10⁻¹⁸ m) · Taşıyıcı: W ve Z bozonu</text>\n  <rect x="360" y="150" width="320" height="90" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">4. KÜTLE ÇEKİM KUVVETİ (En Zayıf)</text>\n  <text x="375" y="191" font-size="10.5" fill="#14532d">• Görevi: Kütle/enerji sahibi tüm gök cisimlerini</text>\n  <text x="383" y="206" font-size="10.5" fill="#14532d">(gezegen, yıldız, galaksi) bir arada tutar; çekicidir.</text>\n  <text x="375" y="223" font-size="10.5" font-weight="bold" fill="#15803d">• Menzil: Sonsuz (F = G·m₁·m₂/d²) · Taşıyıcı: Graviton</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEMEL KUVVETLERİN BENZERLİK VE FARKLILIK KARŞILAŞTIRMASI</text>\n  <rect x="25" y="45" width="650" height="195" rx="10" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/>\n  <rect x="25" y="45" width="650" height="32" rx="10" fill="#e2e8f0"/>\n  <text x="115" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0f172a">Temel Kuvvet</text>\n  <text x="260" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0f172a">Bağıl Şiddet</text>\n  <text x="395" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0f172a">Etki Menzili</text>\n  <text x="560" y="66" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0f172a">Yönü ve Etki Ettiği Tanecik</text>\n  <line x1="25" y1="115" x2="675" y2="115" stroke="#cbd5e1" stroke-width="1"/>\n  <line x1="25" y1="155" x2="675" y2="155" stroke="#cbd5e1" stroke-width="1"/>\n  <line x1="25" y1="195" x2="675" y2="195" stroke="#cbd5e1" stroke-width="1"/>\n  <text x="115" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">1. Güçlü Nükleer</text>\n  <text x="260" y="100" text-anchor="middle" font-size="11" fill="#0f172a">1 (En Büyük)</text>\n  <text x="395" y="100" text-anchor="middle" font-size="11" fill="#0f172a">Çok Kısa (Çekirdek)</text>\n  <text x="560" y="100" text-anchor="middle" font-size="10.5" fill="#0f172a">Çekici · Proton ve Nötronlar</text>\n  <text x="115" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">2. Elektromanyetik</text>\n  <text x="260" y="140" text-anchor="middle" font-size="11" fill="#0f172a">~10⁻² (1/137)</text>\n  <text x="395" y="140" text-anchor="middle" font-size="11" fill="#0f172a">Sonsuz Menzilli</text>\n  <text x="560" y="140" text-anchor="middle" font-size="10.5" fill="#0f172a">İtici ve Çekici · Elektrik Yükleri</text>\n  <text x="115" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">3. Zayıf Nükleer</text>\n  <text x="260" y="180" text-anchor="middle" font-size="11" fill="#0f172a">~10⁻¹³</text>\n  <text x="395" y="180" text-anchor="middle" font-size="11" fill="#0f172a">Çok Kısa (Çekirdek)</text>\n  <text x="560" y="180" text-anchor="middle" font-size="10.5" fill="#0f172a">Bozunma · Kararsız Çekirdekler</text>\n  <text x="115" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">4. Kütle Çekim</text>\n  <text x="260" y="220" text-anchor="middle" font-size="11" fill="#0f172a">~10⁻³⁹ (En Zayıf)</text>\n  <text x="395" y="220" text-anchor="middle" font-size="11" fill="#0f172a">Sonsuz Menzilli</text>\n  <text x="560" y="220" text-anchor="middle" font-size="10.5" fill="#0f172a">Daima Çekici · Kütleli Cisimler</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİLEŞKE KUVVET (R) VE DENGELENMİŞ / DENGELENMEMİŞ KUVVETLER</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">DENGELENMİŞ KUVVETLER (ΣF = R = 0)</text>\n  <rect x="147" y="95" width="70" height="40" rx="6" fill="#bbf7d0" stroke="#15803d" stroke-width="2"/>\n  <text x="182" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">m</text>\n  <line x1="147" y1="115" x2="75" y2="115" stroke="#dc2626" stroke-width="3"/>\n  <polygon points="75,115 85,109 85,121" fill="#dc2626"/>\n  <text x="105" y="105" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">F₁ = 20 N</text>\n  <line x1="217" y1="115" x2="289" y2="115" stroke="#2563eb" stroke-width="3"/>\n  <polygon points="289,115 279,109 279,121" fill="#2563eb"/>\n  <text x="255" y="105" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">F₂ = 20 N</text>\n  <text x="182" y="162" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Net Kuvvet: R = 0 · İvme: a = 0</text>\n  <text x="42" y="188" font-size="11" fill="#14532d">• Duran cisim durmaya devam eder (statik denge).</text>\n  <text x="42" y="210" font-size="11" fill="#14532d">• Hareketli cisim sabit hızla gider (dinamik denge).</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">DENGELENMEMİŞ KUVVETLER (ΣF = R ≠ 0)</text>\n  <rect x="470" y="95" width="70" height="40" rx="6" fill="#fed7aa" stroke="#c2410c" stroke-width="2"/>\n  <text x="505" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#7c2d12">m</text>\n  <line x1="470" y1="115" x2="415" y2="115" stroke="#dc2626" stroke-width="3"/>\n  <polygon points="415,115 425,109 425,121" fill="#dc2626"/>\n  <text x="440" y="105" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">F₁ = 15 N</text>\n  <line x1="540" y1="115" x2="635" y2="115" stroke="#2563eb" stroke-width="3"/>\n  <polygon points="635,115 625,109 625,121" fill="#2563eb"/>\n  <text x="590" y="105" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">F₂ = 35 N</text>\n  <text x="517" y="162" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">Net Kuvvet: R = +20 N (+x yönünde) · a ≠ 0</text>\n  <text x="377" y="188" font-size="11" fill="#7c2d12">• Cisim ivmeli hareket (hızlanma/yavaşlama) yapar.</text>\n  <text x="377" y="210" font-size="11" fill="#7c2d12">• Dengeleyici kuvvet: F_d = -R = -20 N (-x yönü).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
